package com.infinix.smart10.fastlock;
import android.app.Activity;import android.os.Bundle;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import android.content.Intent;
public class LockLayerActivity extends Activity{
@Override public void onCreate(Bundle b){super.onCreate(b);if(android.os.Build.VERSION.SDK_INT>=27)setShowWhenLocked(true);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SHOW_WHEN_LOCKED|WindowManager.LayoutParams.FLAG_TURN_SCREEN_ON);FrameLayout r=new FrameLayout(this);r.setBackgroundColor(Color.TRANSPARENT);TextView d=new TextView(this);d.setText("⌾");d.setTextColor(Color.WHITE);d.setTextSize(27);d.setGravity(Gravity.CENTER);GradientDrawable g=new GradientDrawable();g.setColor(0xEE171A21);g.setShape(GradientDrawable.OVAL);g.setStroke(2,0xFFD8B35A);d.setBackground(g);d.setOnClickListener(v->startActivity(new Intent(this,AuthActivity.class)));FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(76,76,Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL);p.bottomMargin=28;r.addView(d,p);setContentView(r);}}
